/* ==========================================================================
   Enterprise Expert Knowledge Worker — front-end
   Vanilla JS, no build step. Sections:
   1. State & helpers      2. Markdown renderer     3. Navigation & role switcher
   4. Chat + stored history 5. Agent graph & ticker  6. Library + Upload Center
   7. Activity / Benchmarks / Agents   8. Updates & FAQ   9. Boot
   Security note: every piece of dynamic text goes through esc() and no inline
   event handlers are used, so uploaded document titles/text can never run script.
   ========================================================================== */

/* ---------- 1. State & helpers ---------- */
const ROLE_COLORS = { employee: "#2bd48a", manager: "#2d8cff", hr: "#b48cff", legal: "#ffb020", admin: "#ff4d5e" };
const GRAPH_NODES = [
  { id: "Supervisor Agent", label: "Supervisor", x: 200, y: 30 },
  { id: "Planner Agent", label: "Planner", x: 80, y: 85 },
  { id: "Employee Agent", label: "Employee", x: 60, y: 140 },
  { id: "Product Agent", label: "Product", x: 150, y: 140 },
  { id: "Scribe", label: "Scribe", x: 250, y: 140 },
  { id: "Contract Agent", label: "Contract", x: 340, y: 140 },
  { id: "Retrieval Agent", label: "Retrieval", x: 200, y: 195 },
  { id: "Verification Agent", label: "Verification", x: 110, y: 240 },
  { id: "Response Agent", label: "Response", x: 290, y: 240 }
];
const GRAPH_EDGES = [
  ["Supervisor Agent", "Planner Agent"], ["Supervisor Agent", "Contract Agent"], ["Supervisor Agent", "Scribe"],
  ["Supervisor Agent", "Retrieval Agent"], ["Planner Agent", "Employee Agent"], ["Employee Agent", "Product Agent"],
  ["Product Agent", "Scribe"], ["Scribe", "Retrieval Agent"], ["Contract Agent", "Retrieval Agent"],
  ["Retrieval Agent", "Verification Agent"], ["Verification Agent", "Response Agent"]
];
const VIEWS = ["knowledge", "agents", "sources", "activity", "evaluation", "updates", "faq"];

const state = {
  role: "employee",
  sessionId: null,
  sessions: [],
  sending: false,
  sources: [],
  sourceCounts: {},
  filter: "all",
  search: "",
  page: 1,
  uploadCategory: "policy",
  pendingFiles: [],
  faq: [],
  faqCat: "All",
  faqQuery: "",
  pendingGeneralQuery: "",
  stats: null
};
const PAGE_SIZE = 15;

const $ = (id) => document.getElementById(id);
const esc = (v) => String(v ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[c]));

async function api(method, path, body) {
  const opts = { method, headers: {} };
  if (body !== undefined) { opts.headers["Content-Type"] = "application/json"; opts.body = JSON.stringify(body); }
  const res = await fetch(path, opts);
  let data = {};
  try { data = await res.json(); } catch (_) { /* non-JSON error page */ }
  if (!res.ok || data.error) {
    const err = new Error(data.error || `Request failed (${res.status})`);
    err.status = res.status; err.data = data;
    throw err;
  }
  return data;
}

function toast(message, kind = "") {
  const el = document.createElement("div");
  el.className = `toast ${kind}`;
  el.textContent = message;
  $("toasts").appendChild(el);
  setTimeout(() => el.remove(), 4800);
}

function parseServerDate(str) {
  if (!str) return null;
  const d = new Date(String(str).replace(" ", "T"));
  return isNaN(d) ? null : d;
}
function relTime(str) {
  const d = parseServerDate(str);
  if (!d) return "";
  const s = Math.max(0, (Date.now() - d.getTime()) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.floor(s / 60)} min ago`;
  if (s < 86400) return `${Math.floor(s / 3600)} h ago`;
  if (s < 604800) return `${Math.floor(s / 86400)} d ago`;
  return d.toLocaleDateString();
}
function fmtBytes(n) {
  if (n < 1024) return `${n} B`;
  if (n < 1048576) return `${(n / 1024).toFixed(0)} KB`;
  return `${(n / 1048576).toFixed(1)} MB`;
}
const pct = (v) => (typeof v === "number" ? `${Math.round(v * 100)}%` : esc(v));

/* ---------- 2. Markdown renderer (escapes everything first) ---------- */
function mdInline(escaped) {
  return escaped
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/(^|[^*\w])\*([^*\s][^*]*?)\*(?!\w)/g, "$1<em>$2</em>");
}
function renderMarkdown(md) {
  const lines = String(md ?? "").replace(/\r/g, "").split("\n");
  const out = [];
  const isBlockStart = (l) => /^(#{1,4}\s|>\s?|\s*[-*]\s+|\s*\d+\.\s+|```|\s*\|.*\|\s*$|---+\s*$)/.test(l);
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (/^```/.test(line)) {
      const buf = []; i++;
      while (i < lines.length && !/^```/.test(lines[i])) buf.push(lines[i++]);
      i++;
      out.push(`<pre><code>${esc(buf.join("\n"))}</code></pre>`);
      continue;
    }
    if (!line.trim()) { i++; continue; }
    const h = line.match(/^(#{1,4})\s+(.*)$/);
    if (h) { out.push(`<h${h[1].length}>${mdInline(esc(h[2]))}</h${h[1].length}>`); i++; continue; }
    if (/^---+\s*$/.test(line)) { out.push("<hr>"); i++; continue; }
    if (/^\s*\|.*\|\s*$/.test(line) && i + 1 < lines.length && /^\s*\|[\s:|-]+\|\s*$/.test(lines[i + 1])) {
      const cells = (l) => l.trim().replace(/^\||\|$/g, "").split("|").map((c) => mdInline(esc(c.trim())));
      const head = cells(line); i += 2;
      const rows = [];
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) rows.push(cells(lines[i++]));
      out.push(`<table><thead><tr>${head.map((c) => `<th>${c}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`);
      continue;
    }
    if (/^>\s?/.test(line)) {
      const buf = [];
      while (i < lines.length && /^>\s?/.test(lines[i])) buf.push(lines[i++].replace(/^>\s?/, ""));
      out.push(`<blockquote>${mdInline(esc(buf.join("\n"))).replace(/\n/g, "<br>")}</blockquote>`);
      continue;
    }
    if (/^\s*[-*]\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) items.push(lines[i++].replace(/^\s*[-*]\s+/, ""));
      out.push(`<ul>${items.map((t) => `<li>${mdInline(esc(t))}</li>`).join("")}</ul>`);
      continue;
    }
    if (/^\s*\d+\.\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) items.push(lines[i++].replace(/^\s*\d+\.\s+/, ""));
      out.push(`<ol>${items.map((t) => `<li>${mdInline(esc(t))}</li>`).join("")}</ol>`);
      continue;
    }
    const buf = [];
    while (i < lines.length && lines[i].trim() && !isBlockStart(lines[i])) buf.push(lines[i++]);
    if (!buf.length) { buf.push(lines[i++]); }
    out.push(`<p>${mdInline(esc(buf.join("\n"))).replace(/\n/g, "<br>")}</p>`);
  }
  return out.join("");
}

/* ---------- 3. Navigation & role switcher ---------- */
function navigate(pageId, updateHash = true) {
  if (!VIEWS.includes(pageId)) pageId = "knowledge";
  VIEWS.forEach((v) => {
    $(`view-${v}`).classList.toggle("active", v === pageId);
    $(`nav-${v}`).classList.toggle("active", v === pageId);
  });
  $("nav-links").classList.remove("open");
  $("nav-toggle").setAttribute("aria-expanded", "false");
  if (updateHash && location.hash !== `#${pageId}`) history.replaceState(null, "", `#${pageId}`);
  window.scrollTo({ top: 0, behavior: "auto" });

  if (pageId === "sources") loadSources();
  if (pageId === "activity") loadActivity();
  if (pageId === "agents") loadAgents();
  if (pageId === "evaluation") loadEvaluation();
  if (pageId === "updates") loadUpdates();
  if (pageId === "faq") loadFaq();
}

function onRoleChange() {
  state.role = $("role-selector").value;
  $("role-dot").style.background = ROLE_COLORS[state.role];
  $("role-dot").style.boxShadow = `0 0 10px ${ROLE_COLORS[state.role]}`;
  localStorage.setItem("ekw.role", state.role);
  startNewChat(true, false);   // keep this persona's "last opened chat" so it can be restored below
  refreshHistory().then(() => {
    const last = localStorage.getItem(`ekw.session.${state.role}`);
    if (last && state.sessions.some((s) => s.session_id === last)) openSession(last, true);
  });
  if ($("view-sources").classList.contains("active")) renderSources();
  toast(`Persona switched to ${$("role-selector").selectedOptions[0].text}`);
}

/* ---------- 4. Chat + stored history ---------- */
function stream() { return $("chat-stream"); }
function scrollStream() { const s = stream(); s.scrollTop = s.scrollHeight; }

function emptyState() {
  stream().innerHTML = `<div class="empty-state"><img src="/bot_icon.jpg" alt="AI Assistant" style="width: 120px; height: 120px; border-radius: 50%; box-shadow: 0 10px 20px rgba(0,0,0,0.3); margin-bottom: 20px;"><div class="big">Happy to help you</div><h3>Ask anything about your company</h3><p>Policies, products and contracts — with citations, permission checks and human approval for actions. Every conversation is saved automatically.</p></div>`;
}

function addUser(text) {
  clearEmpty();
  const d = document.createElement("div");
  d.className = "msg user";
  d.innerHTML = `<div class="msg-who">You</div><div class="bubble-user">${esc(text)}</div>`;
  stream().appendChild(d); scrollStream();
}
function addSystem(text) {
  clearEmpty();
  const d = document.createElement("div");
  d.className = "msg system";
  d.innerHTML = `<div class="bubble-sys">${esc(text)}</div>`;
  stream().appendChild(d); scrollStream();
}
function clearEmpty() { const e = stream().querySelector(".empty-state"); if (e) e.remove(); }

function addThinking() {
  clearEmpty();
  const d = document.createElement("div");
  d.className = "msg assistant"; d.id = "thinking";
  d.innerHTML = `<div class="msg-who">SCRIBE</div><div class="typing"><i></i><i></i><i></i></div>`;
  stream().appendChild(d); scrollStream();
}
function removeThinking() { const t = $("thinking"); if (t) t.remove(); }

function approvalCard(app, status) {
  const resolved = status === "APPROVED" || status === "REJECTED";
  const cls = status === "APPROVED" ? "approved" : status === "REJECTED" ? "rejected" : "";
  const badge = status === "APPROVED" ? '<span class="badge ok">Approved</span>' : status === "REJECTED" ? '<span class="badge danger">Rejected</span>' : '<span class="badge warn">Action request required</span>';
  return `
    <div class="approval-card ${cls}" data-request="${esc(app.request_id)}">
      <div class="approval-head"><h4>${esc(app.action_type)}</h4>${badge}</div>
      <div class="approval-body">
        <dl>
          <dt>Request ID</dt><dd>${esc(app.request_id)}</dd>
          <dt>Employee</dt><dd>${esc(app.employee_name)} (${esc(app.employee_id)})</dd>
          <dt>Reason</dt><dd>${esc(app.reason)}</dd>
          <dt>Evidence</dt><dd>${esc(app.evidence_source)}</dd>
          <dt>Operation</dt><dd>${esc(app.requested_operation)}</dd>
        </dl>
        <div class="approval-actions" data-actions="${esc(app.request_id)}">
          ${resolved
            ? `<span class="mono ${status === "APPROVED" ? "accent" : "dim"}">${status === "APPROVED" ? "✓ Recorded in the enterprise database and audit ledger." : "✗ Rejected by a human auditor."}</span>`
            : `<button class="btn btn-danger btn-sm" data-decision="reject" data-request="${esc(app.request_id)}">Reject</button>
               <button class="btn btn-primary btn-sm" data-decision="approve" data-request="${esc(app.request_id)}">Approve request</button>`}
        </div>
      </div>
    </div>`;
}

function renderHumanConfirmation(responseText) {
  const shouldPrompt = /human-in-the-loop|required|Yes, continue with general guidance|No to stop/i.test(String(responseText || ""));
  if (!shouldPrompt) return "";
  return `
    <div class="confirmation-row" style="display:flex; gap:8px; margin-top:12px; margin-bottom:6px; flex-wrap:wrap;">
      <button class="btn btn-primary btn-sm" data-confirm-guidance="yes">Yes</button>
      <button class="btn btn-ghost btn-sm" data-confirm-guidance="no">No</button>
    </div>`;
}

function renderAssistant(data) {
  const denied = !!data.is_permission_denied;
  const badges = [];
  if (denied) badges.push('<span class="badge danger">Access denied</span>');
  else if (data.is_action_request) badges.push('<span class="badge warn">Approval pending</span>');
  else if ((data.evidence_status || "Verified") === "Verified") badges.push('<span class="badge ok">Grounded &amp; verified</span>');
  else badges.push(`<span class="badge warn">${esc(data.evidence_status)}</span>`);

  let html = `<div class="evidence-row">${badges.join("")}</div>`;
  if (data.plan && data.plan.steps && data.plan.steps.length) {
    html += `<div class="plan-card"><div class="plan-title">Strategic execution plan · ${data.plan.steps.length} steps${data.plan.complexity ? ` · ${esc(data.plan.complexity)}` : ""}</div>${data.plan.steps.map((s, i) => `<div class="plan-step"><span class="plan-num">${String(i + 1).padStart(2, "0")}</span><span>${esc(s)}</span></div>`).join("")}</div>`;
  }
  html += `<div class="md">${renderMarkdown(data.response)}</div>`;
  html += renderHumanConfirmation(data.response);
  if (data.is_action_request && data.action_approval) html += approvalCard(data.action_approval, data.approval_status);
  if (data.citations && data.citations.length) {
    html += `<div class="cite-wrap"><div class="cite-title">Authoritative sources &amp; citations</div><div class="cite-list">${data.citations.map((c) => `
      <button class="cite" data-file="${esc(c.file_name || "")}" data-title="${esc(c.document_name)}">
        <div class="cite-top"><span class="cite-name">${esc(c.document_name)}</span>${c.rerank_score != null ? `<span class="cite-score">${Math.round(c.rerank_score * 100)}% match</span>` : ""}</div>
        <div class="cite-sec">${esc(c.section)} · ${esc(c.version || "v1.0")}</div>
        ${c.content_preview ? `<div class="cite-quote">“${esc(c.content_preview.slice(0, 160))}${c.content_preview.length > 160 ? "…" : ""}”</div>` : ""}
      </button>`).join("")}</div></div>`;
  }
  if (data.execution_trace && data.execution_trace.length) {
    html += `<div class="trace-line">Agent trace · ${data.execution_trace.length} nodes: ${data.execution_trace.map((t) => esc(String(t.agent).replace(" Agent", ""))).join(" → ")}</div>`;
  }
  const d = document.createElement("div");
  d.className = "msg assistant";
  d.innerHTML = `<div class="msg-who">SCRIBE</div><div class="bubble"><div class="answer ${denied ? "denied" : ""}">${html}</div></div>`;
  return d;
}

function setStatusBadge(data) {
  const b = $("chat-status-badge");
  if (data.is_permission_denied) { b.className = "badge danger"; b.textContent = "Access denied"; }
  else if (data.is_action_request) { b.className = "badge warn"; b.textContent = "Approval pending"; }
  else { b.className = "badge ok"; b.textContent = "Grounded & verified"; }
}

async function sendQuery(text) {
  const query = (text || "").trim();
  if (!query || state.sending) return;
  state.pendingGeneralQuery = query;
  state.sending = true;
  ["btn-submit", "chat-send"].forEach((id) => { const el = $(id); if(el) el.disabled = true; });
  if (!$("view-knowledge").classList.contains("active")) navigate("knowledge", true);
  $("workspace").scrollIntoView({ behavior: "smooth", block: "start" });

  addUser(query);
  $("query-input").value = ""; $("chat-input").value = "";
  addThinking();
  resetGraph(); highlightNode("Supervisor Agent", "active");
  const gLabel = $("graph-state-label"); if (gLabel) gLabel.textContent = "Executing…";

  try {
    const data = await api("POST", "/api/chat", { query, user_role: state.role, session_id: state.sessionId });
    removeThinking();
    state.sessionId = data.session_id;
    localStorage.setItem(`ekw.session.${state.role}`, state.sessionId);
    $("chat-title-text").textContent = data.session_title || "Conversation";
    stream().appendChild(renderAssistant(data));
    scrollStream();
    setStatusBadge(data);
    updateGraph(data.graph_nodes_status, data.execution_trace);
    updateActivityStream(data.execution_trace);
    refreshHistory();
    refreshTicker();
    refreshStats();
  } catch (err) {
    removeThinking();
    resetGraph();
    addSystem(`Could not complete the request: ${err.message}`);
  } finally {
    state.sending = false;
    ["btn-submit", "chat-send"].forEach((id) => { const el = $(id); if(el) el.disabled = false; });
    const ci = $("chat-input"); if(ci) ci.focus();
  }
}

async function refreshHistory() {
  try {
    const data = await api("GET", `/api/chats?role=${encodeURIComponent(state.role)}`);
    state.sessions = data.sessions || [];
  } catch (_) { state.sessions = []; }
  renderHistory();
}
function renderHistory() {
  const list = $("history-list");
  if (!state.sessions.length) { list.innerHTML = `<div class="history-empty">No saved chats yet for this persona.<br>Your conversations will appear here.</div>`; return; }
  list.innerHTML = state.sessions.map((s) => `
    <div class="h-item ${s.session_id === state.sessionId ? "active" : ""}" data-session="${esc(s.session_id)}" role="button" tabindex="0">
      <span class="h-title">${esc(s.title)}</span>
      <span class="h-meta">${esc(relTime(s.updated_at))} · ${s.message_count} msgs</span>
      <button class="h-del" data-delete="${esc(s.session_id)}" title="Delete chat" aria-label="Delete chat">🗑</button>
    </div>`).join("");
}

function startNewChat(silent, forget = true) {
  state.sessionId = null;
  if (forget) localStorage.removeItem(`ekw.session.${state.role}`);
  $("chat-title-text").textContent = "New conversation";
  $("chat-status-badge").className = "badge ok"; $("chat-status-badge").textContent = "Ready";
  emptyState(); resetGraph();
  $("activity-stream").innerHTML = `<div class="history-empty">Awaiting query execution…</div>`;
  $("activity-counter").textContent = "0 events";
  $("graph-state-label").textContent = "LangGraph compiled";
  renderHistory();
  $("history").classList.remove("open");
  if (!silent) $("chat-input").focus();
}

async function openSession(sessionId, silent) {
  try {
    const data = await api("GET", `/api/chats/${encodeURIComponent(sessionId)}?role=${encodeURIComponent(state.role)}`);
    state.sessionId = sessionId;
    localStorage.setItem(`ekw.session.${state.role}`, sessionId);
    $("chat-title-text").textContent = data.session.title;
    stream().innerHTML = "";
    let lastAssistant = null;
    data.messages.forEach((m) => {
      if (m.sender === "user") addUser(m.content);
      else if (m.sender === "assistant") {
        lastAssistant = { ...m.data, response: m.content };
        stream().appendChild(renderAssistant(lastAssistant));
      } else addSystem(m.content);
    });
    if (lastAssistant) { setStatusBadge(lastAssistant); updateGraph(lastAssistant.graph_nodes_status, lastAssistant.execution_trace); updateActivityStream(lastAssistant.execution_trace); }
    scrollStream();
    renderHistory();
    $("history").classList.remove("open");
    if (!silent) $("workspace").scrollIntoView({ behavior: "smooth", block: "start" });
  } catch (err) {
    localStorage.removeItem(`ekw.session.${state.role}`);
    if (!silent) toast(err.message, "err");
  }
}

async function deleteSession(sessionId) {
  if (!confirm("Delete this chat permanently from the database?")) return;
  try {
    await api("DELETE", `/api/chats/${encodeURIComponent(sessionId)}?role=${encodeURIComponent(state.role)}`);
    if (state.sessionId === sessionId) startNewChat(true);
    await refreshHistory(); refreshStats();
    toast("Chat deleted", "ok");
  } catch (err) { toast(err.message, "err"); }
}

async function processApproval(requestId, decision) {
  const box = document.querySelector(`[data-actions="${CSS.escape(requestId)}"]`);
  if (box) box.innerHTML = `<span class="mono dim">Submitting decision…</span>`;
  try {
    await api("POST", "/api/approval", {
      request_id: requestId, decision,
      approver_name: state.role === "admin" ? "David Chen (Admin Auditor)" : "Elena Rostova (Manager Auditor)"
    });
    const card = document.querySelector(`.approval-card[data-request="${CSS.escape(requestId)}"]`);
    if (card) {
      const ok = decision === "approve";
      card.classList.add(ok ? "approved" : "rejected");
      card.querySelector(".approval-head .badge").outerHTML = ok ? '<span class="badge ok">Approved</span>' : '<span class="badge danger">Rejected</span>';
      box.innerHTML = `<span class="mono ${ok ? "accent" : "dim"}">${ok ? "✓ Recorded in the enterprise database and audit ledger." : "✗ Rejected by a human auditor."}</span>`;
    }
    refreshTicker();
  } catch (err) {
    if (box) box.innerHTML = `<span class="mono" style="color:var(--danger)">Error: ${esc(err.message)}</span>`;
  }
}

/* ---------- 5. Agent graph, activity stream, ticker, stats ---------- */
const SVGNS = "http://www.w3.org/2000/svg";
const nid = (name) => name.replace(/\s+/g, "");
function initGraph() {
  const svg = $("graph-svg");
  if (!svg) return;
  svg.innerHTML = "";
  GRAPH_EDGES.forEach(([a, b]) => {
    const A = GRAPH_NODES.find((n) => n.id === a), B = GRAPH_NODES.find((n) => n.id === b);
    const line = document.createElementNS(SVGNS, "line");
    line.setAttribute("class", "g-edge"); line.setAttribute("id", `edge-${nid(a)}-${nid(b)}`);
    line.setAttribute("x1", A.x); line.setAttribute("y1", A.y); line.setAttribute("x2", B.x); line.setAttribute("y2", B.y);
    svg.appendChild(line);
  });
  GRAPH_NODES.forEach((n) => {
    const g = document.createElementNS(SVGNS, "g");
    g.setAttribute("class", "g-node"); g.setAttribute("id", `node-${nid(n.id)}`);
    g.setAttribute("transform", `translate(${n.x}, ${n.y})`);
    g.innerHTML = `<circle r="14"></circle><text y="27">${esc(n.label)}</text>`;
    g.style.cursor = "pointer";
    g.addEventListener("click", () => navigate("agents"));
    svg.appendChild(g);
  });
}
function resetGraph() {
  document.querySelectorAll(".g-node").forEach((g) => g.setAttribute("class", "g-node"));
  document.querySelectorAll(".g-edge").forEach((e) => e.setAttribute("class", "g-edge"));
}
function highlightNode(agent, status) {
  const g = $(`node-${nid(agent)}`);
  if (!g) return;
  const map = { active: "active", Completed: "done", "Waiting for approval": "wait", Failed: "fail" };
  g.setAttribute("class", `g-node ${map[status] || ""}`);
}
function updateGraph(nodesStatus, trace) {
  resetGraph();
  if (!nodesStatus) return;
  Object.entries(nodesStatus).forEach(([agent, st]) => highlightNode(agent, st));
  GRAPH_EDGES.forEach(([a, b]) => {
    if (nodesStatus[a] && nodesStatus[b]) { const e = $(`edge-${nid(a)}-${nid(b)}`); if (e) e.setAttribute("class", "g-edge on"); }
  });
  const gLabel = $("graph-state-label"); if (gLabel) gLabel.textContent = `Completed (${trace ? trace.length : 0} nodes)`;
}
function updateActivityStream(trace) {
  if (!trace) return;
  const ac = $("activity-counter"); if (ac) ac.textContent = `${trace.length} events`;
  const as = $("activity-stream"); if (as) as.innerHTML = trace.map((t) => {
    const cls = t.status === "Waiting for approval" ? "warn" : t.status === "Failed" ? "fail" : "";
    return `<div class="act"><span class="act-dot ${cls}"></span><div><b>${esc(t.agent)}</b><span>${esc(t.duration_ms)}ms · ${esc(t.timestamp || "")}</span><p>${esc(t.action)}</p></div></div>`;
  }).join("");
}

async function refreshTicker() {
  try {
    const data = await api("GET", "/api/activity");
    const logs = (data.recent_logs || []).slice(0, 14);
    if (!logs.length) return;
    const item = (l) => {
      const time = (l.timestamp || "").split(" ")[1] || "";
      const ok = l.status === "SUCCESS";
      const badge = ok ? '<span class="badge ok">Verified</span>' : l.status === "PENDING" ? '<span class="badge warn">Pending</span>' : '<span class="badge danger">Blocked</span>';
      return `<span class="tick"><span class="t-time">${esc(time)}</span><span class="t-agent">${esc(l.agent_name)}</span><span>${esc(String(l.details || "").slice(0, 70))}</span>${badge}</span>`;
    };
    const html = logs.map(item).join("");
    $("ticker-inner").innerHTML = html + html; // duplicated for a seamless loop
  } catch (_) { /* ticker is decorative */ }
}

function countUp(el, target) {
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const from = Number(el.dataset.count || 0);
  el.dataset.count = target;
  if (reduce || from === target) { el.textContent = target.toLocaleString(); return; }
  const start = performance.now(), dur = 900;
  const tick = (now) => {
    const p = Math.min(1, (now - start) / dur);
    el.textContent = Math.round(from + (target - from) * (1 - Math.pow(1 - p, 3))).toLocaleString();
    if (p < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}
async function refreshStats() {
  try {
    const s = await api("GET", "/api/stats");
    state.stats = s;
    countUp($("stat-documents"), s.documents); countUp($("stat-policies"), s.policies);
    countUp($("stat-agents"), s.agents); countUp($("stat-chats"), s.chat_sessions);
    $("dx-docs").textContent = `${s.documents}`;
    if ($("metric-chat-messages")) $("metric-chat-messages").textContent = s.chat_messages;
    const sub = $("dz-sub");
    if (sub && s.upload) sub.textContent = `${s.upload.extensions.filter((e) => e !== ".log").join(" · ")} — up to ${s.upload.max_mb} MB each`;
  } catch (_) { /* non-critical */ }
}

/* ---------- 6. Library + Upload Center ---------- */
async function loadSources() {
  try {
    const data = await api("GET", "/api/sources");
    state.sources = data.sources || [];
    state.sourceCounts = data.counts || {};
    $("sources-sub").textContent = `${data.total_sources} indexed documents: governance policies, insurance product specifications, vendor agreements and your uploads.`;
    const c = state.sourceCounts;
    const labels = { all: `All (${data.total_sources})`, policy: `Policies (${c.policy || 0})`, product: `Products (${c.product || 0})`, contract: `Contracts & SLAs (${c.contract || 0})`, uploaded: `Uploaded (${c.uploaded || 0})` };
    document.querySelectorAll("#source-filters .filter").forEach((b) => { b.textContent = labels[b.dataset.filter]; });
    renderSources();
  } catch (err) {
    $("sources-body").innerHTML = `<tr><td colspan="8" style="color:var(--danger)">Error loading sources: ${esc(err.message)}</td></tr>`;
  }
}

function filteredSources() {
  const q = state.search.trim().toLowerCase();
  return state.sources.filter((s) => {
    if (state.filter === "uploaded" && s.origin !== "uploaded") return false;
    if (["policy", "product", "contract"].includes(state.filter) && s.type !== state.filter) return false;
    if (!q) return true;
    return [s.title, s.document_id, s.department, s.filename].some((v) => String(v || "").toLowerCase().includes(q));
  });
}

function renderSources() {
  const all = filteredSources();
  const pages = Math.max(1, Math.ceil(all.length / PAGE_SIZE));
  state.page = Math.min(state.page, pages);
  const rows = all.slice((state.page - 1) * PAGE_SIZE, state.page * PAGE_SIZE);
  $("sources-body").innerHTML = rows.length ? rows.map((s) => {
    const roles = s.access_roles || [];
    const canRead = roles.includes(state.role);
    const canDelete = s.origin === "uploaded" && (state.role === "admin" || s.uploaded_by_role === state.role);
    return `<tr>
      <td><span class="doc-name">${esc(s.title || s.filename)}</span>${s.origin === "uploaded" ? ' <span class="badge info">Uploaded</span>' : ""}<span class="doc-id">${esc(s.document_id || s.filename)}</span></td>
      <td><span class="type-pill">${esc(s.type)}</span></td>
      <td>${esc(s.department)}</td>
      <td>${esc(s.version || "v1.0")}</td>
      <td>${esc(s.last_updated || "")}</td>
      <td>${esc(s.chunks_count)}</td>
      <td>${roles.map((r) => `<span class="role-pill ${esc(r)}">${esc(r)}</span>`).join("")}</td>
      <td><div class="row-actions">
        <button class="btn btn-ghost btn-xs" data-inspect="${esc(s.filename)}" title="${canRead ? "Read the document" : "Your persona cannot read this document"}">${canRead ? "Inspect" : "🔒 Inspect"}</button>
        ${canDelete ? `<button class="btn btn-danger btn-xs" data-del="${esc(s.document_id)}" data-name="${esc(s.title)}">Delete</button>` : ""}
      </div></td></tr>`;
  }).join("") : `<tr><td colspan="8" class="faq-empty" style="text-align:center">No documents match.</td></tr>`;

  $("sources-pager").innerHTML = all.length > PAGE_SIZE
    ? `<span>Showing ${(state.page - 1) * PAGE_SIZE + 1}–${Math.min(state.page * PAGE_SIZE, all.length)} of ${all.length}</span>
       <div class="pager-btns"><button class="btn btn-ghost btn-xs" data-page="prev" ${state.page === 1 ? "disabled" : ""}>← Prev</button><button class="btn btn-ghost btn-xs" data-page="next" ${state.page === pages ? "disabled" : ""}>Next →</button></div>`
    : `<span>${all.length} document${all.length === 1 ? "" : "s"}</span>`;
}

async function openDocument(fileName, titleHint) {
  if (!state.sources.length) { try { state.sources = (await api("GET", "/api/sources")).sources || []; } catch (_) { /* fall through */ } }
  let file = fileName;
  if (!file && titleHint) {
    const hit = state.sources.find((s) => s.title === titleHint);
    file = hit ? hit.filename : "";
  }
  $("modal-doc-title").textContent = titleHint || "Document";
  $("modal-doc-meta").innerHTML = "";
  $("modal-doc-content").innerHTML = `<p class="dim">Loading…</p>`;
  $("doc-modal").classList.add("open"); $("doc-modal").setAttribute("aria-hidden", "false");
  if (!file) { $("modal-doc-content").innerHTML = `<p>This document could not be located in the library.</p>`; return; }
  try {
    const d = await api("GET", `/api/document?file=${encodeURIComponent(file)}&role=${encodeURIComponent(state.role)}`);
    $("modal-doc-title").textContent = d.title;
    $("modal-doc-meta").innerHTML = [["Type", d.type], ["Department", d.department], ["Version", d.version], ["Updated", d.last_updated], ["ID", d.document_id || "—"], ["Access", d.access_roles.join(", ")]]
      .map(([k, v]) => `<span>${esc(k)}: <b>${esc(v)}</b></span>`).join("");
    const lines = d.content.split("\n");
    const blank = lines.findIndex((l, i) => i > 0 && !l.trim());
    $("modal-doc-content").innerHTML = renderMarkdown(lines.slice(blank > 0 ? blank : 0).join("\n"));
  } catch (err) {
    const roles = err.data && err.data.required_roles ? ` Required roles: ${err.data.required_roles.join(", ").toUpperCase()}.` : "";
    $("modal-doc-title").textContent = (err.data && err.data.title) || "Restricted document";
    $("modal-doc-content").innerHTML = `<blockquote>⛔ ${esc(err.message)}${esc(roles)} Switch to an authorised persona to read it.</blockquote>`;
  }
}
function closeModal() { $("doc-modal").classList.remove("open"); $("doc-modal").setAttribute("aria-hidden", "true"); }

/* Upload Center */
function toBase64(buffer) {
  const bytes = new Uint8Array(buffer); let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  return btoa(bin);
}
async function uploadOne(file, opts = {}) {
  const buffer = await file.arrayBuffer();
  return api("POST", "/api/upload", {
    filename: file.name, content_base64: toBase64(buffer), user_role: state.role,
    category: opts.category || "policy", title: opts.title || "", department: opts.department || "", access_roles: opts.roles
  });
}
function checkFile(file) {
  const ext = (file.name.match(/\.[^.]+$/) || [""])[0].toLowerCase();
  const allowed = state.stats ? state.stats.upload.extensions : [".md", ".txt", ".csv", ".json", ".docx", ".pdf"];
  const max = (state.stats ? state.stats.upload.max_mb : 5) * 1048576;
  if (!allowed.includes(ext)) return `${ext || "This type"} is not supported`;
  if (file.size > max) return `Larger than ${max / 1048576} MB`;
  if (file.size === 0) return "File is empty";
  return "";
}
function addPendingFiles(fileList) {
  state.pendingFiles = state.pendingFiles.filter((p) => p.status !== "done");   // clear last batch's finished items
  Array.from(fileList).forEach((file) => {
    const problem = checkFile(file);
    state.pendingFiles.push({ file, status: problem ? "err" : "ready", message: problem });
  });
  renderPending();
}
function renderPending() {
  $("upload-list").innerHTML = state.pendingFiles.map((p) => `
    <li class="up-item"><span><span class="up-name">${esc(p.file.name)}</span><span class="up-size">${fmtBytes(p.file.size)}</span></span>
      <span class="up-status ${p.status === "done" ? "ok" : p.status === "err" ? "err" : p.status === "busy" ? "busy" : ""}">${
        p.status === "ready" ? "Ready" : p.status === "busy" ? "Uploading & indexing…" : esc(p.message)}</span></li>`).join("");
  $("btn-upload").disabled = !state.pendingFiles.some((p) => p.status === "ready");
}
async function runUpload() {
  const roles = Array.from(document.querySelectorAll("#upload-roles input:checked")).map((i) => i.value);
  const ready = state.pendingFiles.filter((p) => p.status === "ready");
  const btn = $("btn-upload"); btn.disabled = true; btn.textContent = "Uploading…";
  for (const p of ready) {
    p.status = "busy"; renderPending();
    try {
      const r = await uploadOne(p.file, {
        category: state.uploadCategory, roles,
        title: ready.length === 1 ? $("upload-title").value.trim() : "",
        department: $("upload-dept").value.trim()
      });
      p.status = "done"; p.message = `✓ Indexed · ${r.chunks_count} sections`;
    } catch (err) { p.status = "err"; p.message = err.message; }
    renderPending();
  }
  btn.textContent = "Upload & index";
  const okCount = state.pendingFiles.filter((p) => p.status === "done").length;
  if (okCount) { toast(`${okCount} document${okCount > 1 ? "s" : ""} added to the knowledge base. You can ask about ${okCount > 1 ? "them" : "it"} now.`, "ok"); $("upload-title").value = ""; }
  renderPending(); loadSources(); refreshStats(); refreshTicker();
}
async function uploadFromChat(file) {
  if (!file) return;
  const problem = checkFile(file);
  if (problem) { toast(`${file.name}: ${problem}`, "err"); return; }
  if (!$("view-knowledge").classList.contains("active")) navigate("knowledge");
  addSystem(`📎 Uploading “${file.name}” to the knowledge base…`);
  try {
    const r = await uploadOne(file, { category: "policy" });
    addSystem(`✓ “${r.title}” added (${r.chunks_count} sections indexed, readable by: ${r.access_roles.join(", ")}). Ask me anything about it.`);
    loadSources(); refreshStats(); refreshTicker();
  } catch (err) { addSystem(`Upload failed: ${err.message}`); }
}
async function deleteUpload(docId, name) {
  if (!confirm(`Delete “${name}” from the knowledge base?`)) return;
  try {
    await api("DELETE", `/api/uploads/${encodeURIComponent(docId)}?role=${encodeURIComponent(state.role)}`);
    toast("Document removed", "ok");
    loadSources(); refreshStats();
  } catch (err) { toast(err.message, "err"); }
}

