    $("updates-list").innerHTML = (data.updates || []).map((u) => `
      <article class="release">
        <div class="release-side"><div class="ver">${esc(u.version)}</div><span class="mono">${esc(u.date)}</span><span class="badge ${u.tag === "Latest" ? "ok" : "info"}">${esc(u.tag)}</span></div>
        <div><h3>${esc(u.title)}</h3><ul class="rel-items">${u.items.map((i) => `<li><span class="badge ${i.type === "Security" ? "danger" : i.type === "New" ? "ok" : "info"}">${esc(i.type)}</span><span>${esc(i.text)}</span></li>`).join("")}</ul></div>
      </article>`).join("");
