async function loadFaq() {
  // Fetched every time the page opens, because popular questions are added to it automatically
  try { state.faq = (await api("GET", "/api/faq")).faq || []; }
  catch (err) { $("faq-list").innerHTML = `<p style="color:var(--danger)">${esc(err.message)}</p>`; return; }
  const cats = ["All", ...Array.from(new Set(state.faq.map((f) => f.category)))];
  if (!cats.includes(state.faqCat)) state.faqCat = "All";
  $("faq-filters").innerHTML = cats.map((c) => `<button class="filter ${c === state.faqCat ? "active" : ""}" data-faqcat="${esc(c)}">${esc(c)}</button>`).join("");
  renderFaq();
}
function renderFaq() {
  const q = state.faqQuery.trim().toLowerCase();
  const items = state.faq.filter((f) => (state.faqCat === "All" || f.category === state.faqCat) && (!q || `${f.q} ${f.a}`.toLowerCase().includes(q)));
  if (!items.length) { $("faq-list").innerHTML = `<div class="faq-empty">No questions match “${esc(state.faqQuery)}”. Try different words, or ask the assistant directly.</div>`; return; }
  let html = "", lastCat = "";
  items.forEach((f) => {
    if (state.faqCat === "All" && f.category !== lastCat) { html += `<div class="faq-cat">${esc(f.category)}</div>`; lastCat = f.category; }
    // Auto-added entries carry a markdown answer (rendered through the escaping renderer) and their sources
    const answer = f.auto
      ? `<div class="md">${renderMarkdown(f.a)}</div>${(f.sources || []).length ? `<div class="faq-src">Sources: ${f.sources.map((x) => `${esc(x.document_name)} (${esc(x.section)})`).join(" · ")}</div>` : ""}`
      : esc(f.a);
    const badge = f.auto ? `<span class="badge info faq-asked">Asked ${esc(f.asked)}×</span>` : "";
    html += `<div class="faq-item"><button class="faq-q" aria-expanded="false"><span>${esc(f.q)} ${badge}</span><span class="plus">+</span></button><div class="faq-a">${answer}</div></div>`;
  });
  $("faq-list").innerHTML = html;
}

/* ---------- 9. Boot & event wiring ---------- */
document.addEventListener("DOMContentLoaded", () => {
  initGraph();
  emptyState();

  const savedRole = localStorage.getItem("ekw.role");
  if (savedRole && ROLE_COLORS[savedRole]) { state.role = savedRole; $("role-selector").value = savedRole; }
  $("role-dot").style.background = ROLE_COLORS[state.role];
  $("role-dot").style.boxShadow = `0 0 10px ${ROLE_COLORS[state.role]}`;

  // Navigation
  window.addEventListener("hashchange", () => navigate(location.hash.replace("#", "") || "knowledge", false));
  $("nav-toggle").addEventListener("click", () => {
    const open = $("nav-links").classList.toggle("open");
    $("nav-toggle").setAttribute("aria-expanded", String(open));
  });
  ["nav-cta", "cta-ask"].forEach((id) => $(id).addEventListener("click", (e) => {
    e.preventDefault(); navigate("knowledge"); $("query-input").focus();
  }));
  $("role-selector").addEventListener("change", onRoleChange);

  // Ask boxes
  $("btn-submit").addEventListener("click", () => sendQuery($("query-input").value));
  $("query-input").addEventListener("keydown", (e) => { if (e.key === "Enter") sendQuery($("query-input").value); });
  $("chat-send").addEventListener("click", () => sendQuery($("chat-input").value));
  $("chat-input").addEventListener("keydown", (e) => { if (e.key === "Enter") sendQuery($("chat-input").value); });
  $("btn-new-chat").addEventListener("click", () => startNewChat(false));
  $("history-toggle").addEventListener("click", () => $("history").classList.toggle("open"));
  ["hero-attach", "chat-attach"].forEach((id) => {
    const el = $(id);
    if (el) {
      el.addEventListener("click", () => {
        const fileInput = $("chat-file-input");
        if (fileInput) fileInput.click();
      });
    }
  });
  const fileInput = $("chat-file-input");
  if (fileInput) {
    fileInput.addEventListener("change", (e) => { uploadFromChat(e.target.files[0]); e.target.value = ""; });
  }

  // One delegated click handler for everything dynamic
  document.addEventListener("click", (e) => {
    const t = e.target;
    const q = t.closest("[data-query]"); if (q) { sendQuery(q.dataset.query); return; }
    const del = t.closest("[data-delete]"); if (del) { e.stopPropagation(); deleteSession(del.dataset.delete); return; }
    const item = t.closest(".h-item"); if (item) { openSession(item.dataset.session); return; }
    const cite = t.closest(".cite"); if (cite) { openDocument(cite.dataset.file, cite.dataset.title); return; }
    const dec = t.closest("[data-decision]"); if (dec) { processApproval(dec.dataset.request, dec.dataset.decision); return; }
    const confirmBtn = t.closest("[data-confirm-guidance]"); if (confirmBtn) {
      const decision = confirmBtn.dataset.confirmGuidance === "yes"
        ? "Yes, continue with general guidance"
        : "No, stop and route this to a human policy owner";
      const originalQuery = state.pendingGeneralQuery || "";
      state.pendingGeneralQuery = originalQuery;
      
      const actionCard = confirmBtn.closest(".action-card");
      if (actionCard) {
        actionCard.querySelectorAll("button").forEach(b => b.disabled = true);
        actionCard.style.opacity = "0.5";
      }
      
      addUser(decision);
      addThinking();
      
      state.sending = true;
      const payload = {
        query: decision,
        user_role: state.role,
        session_id: state.sessionId,
        context_query: originalQuery
      };
      api("POST", "/api/chat", payload)
        .then((data) => {
          removeThinking();
          state.sessionId = data.session_id;
          localStorage.setItem(`ekw.session.${state.role}`, state.sessionId);
          stream().appendChild(renderAssistant(data));
          scrollStream();
          setStatusBadge(data);
          updateGraph(data.graph_nodes_status, data.execution_trace);
          updateActivityStream(data.execution_trace);
          refreshHistory();
          refreshTicker();
          refreshStats();
        })
        .catch((err) => {
          removeThinking();
          addSystem(`Could not complete the request: ${err.message}`);
        })
        .finally(() => {
          state.sending = false;
          state.pendingGeneralQuery = "";
        });
      return;
    }
    const insp = t.closest("[data-inspect]"); if (insp) { openDocument(insp.dataset.inspect, ""); return; }
    const dl = t.closest("[data-del]"); if (dl) { deleteUpload(dl.dataset.del, dl.dataset.name); return; }
    const flt = t.closest("#source-filters .filter"); if (flt) {
      state.filter = flt.dataset.filter; state.page = 1;
      document.querySelectorAll("#source-filters .filter").forEach((b) => b.classList.toggle("active", b === flt)); renderSources(); return;
    }
    const pg = t.closest("[data-page]"); if (pg) { state.page += pg.dataset.page === "next" ? 1 : -1; renderSources(); return; }
    const fc = t.closest("[data-faqcat]"); if (fc) {
      state.faqCat = fc.dataset.faqcat;
      document.querySelectorAll("#faq-filters .filter").forEach((b) => b.classList.toggle("active", b === fc)); renderFaq(); return;
    }
    const fq = t.closest(".faq-q"); if (fq) {
      const item2 = fq.parentElement; const open = item2.classList.toggle("open"); fq.setAttribute("aria-expanded", String(open)); return;
    }
    const seg = t.closest("#upload-category .seg"); if (seg) {
      state.uploadCategory = seg.dataset.value;
      document.querySelectorAll("#upload-category .seg").forEach((b) => b.classList.toggle("active", b === seg)); return;
    }
    if (t.closest("#modal-close") || t === $("doc-modal")) closeModal();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeModal();
    if ((e.key === "Enter" || e.key === " ") && e.target.classList && e.target.classList.contains("h-item")) { e.preventDefault(); openSession(e.target.dataset.session); }
  });

  // Library filters, upload
  $("source-search").addEventListener("input", (e) => { state.search = e.target.value; state.page = 1; renderSources(); });
  $("faq-search").addEventListener("input", (e) => { state.faqQuery = e.target.value; renderFaq(); });
  const dz = $("dropzone");
  dz.addEventListener("click", () => $("file-input").click());
  dz.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); $("file-input").click(); } });
  ["dragenter", "dragover"].forEach((ev) => dz.addEventListener(ev, (e) => { e.preventDefault(); dz.classList.add("drag"); }));
  ["dragleave", "drop"].forEach((ev) => dz.addEventListener(ev, (e) => { e.preventDefault(); dz.classList.remove("drag"); }));
  dz.addEventListener("drop", (e) => addPendingFiles(e.dataTransfer.files));
  $("file-input").addEventListener("change", (e) => { addPendingFiles(e.target.files); e.target.value = ""; });
  $("btn-upload").addEventListener("click", runUpload);
  $("btn-rerun").addEventListener("click", async () => { $("eval-body").innerHTML = `<tr><td colspan="9" style="text-align:center;padding:24px">Running benchmark across the LangGraph engine…</td></tr>`; await loadEvaluation(); });

  // Initial data
  refreshStats(); refreshTicker();
  setInterval(refreshTicker, 30000);
  refreshHistory().then(() => {
    const last = localStorage.getItem(`ekw.session.${state.role}`);
    if (last && state.sessions.some((s) => s.session_id === last)) openSession(last, true);
  });
  navigate(location.hash.replace("#", "") || "knowledge", false);
});
